import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load brushed metal texture
  const metalTexture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry (512x320 px atlas = 1.6:1 aspect ratio)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Material with brushed metal map
  const planeMaterial = new MeshBasicNodeMaterial({
    map: metalTexture,
    side: THREE.DoubleSide,
  });

  // Plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text "Journal 1" via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const text = config.textContent[0];
    const textMesh = ctx.fontAtlas.render(text, {
      size: 0.34, // headline scale
      color: config.colors.ink,
      align: 'center',
    });
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Apply transforms
  const [px, py, pz] = config.scenePosition;
  const [rx, ry, rz] = config.rotation;
  const [sx, sy, sz] = config.scale;

  group.position.set(px, py, pz);
  group.rotation.order = 'YXZ';
  group.rotation.set(rx, ry, rz);
  group.scale.set(sx, sy, sz);

  // Cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    metalTexture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
